using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SharpenFinCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Cellarius/SharpenFinCustomDescription", order = 0)]
public class SharpenFinCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		SharpenFinAction sharpenFinAction = battleAction as SharpenFinAction;
		string actionDescription = sharpenFinAction.PurifyAction.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		string actionDescription2 = sharpenFinAction.SharpenFinEffectAction.GetActionDescription(1);
		return actionDescription + "\n" + actionDescription2 + "\n" + sharpenFinAction.SharpenFinEffect.GetEffectDescription(0);
	}
}
